import{c as i,Q as a,j as e,m as n}from"./chunks/framework.W-g_WCNV.js";const k=JSON.parse('{"title":"Groups","description":"","frontmatter":{},"headers":[],"relativePath":"admin/groups.md","filePath":"admin/groups.md"}'),t={name:"admin/groups.md"};function r(p,s,l,o,h,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h1><p>Groups let you organize users and expose their membership as a <code>groups</code> claim in OIDC tokens. Apps like Grafana and Jellyfin use this claim for role mapping.</p><h2 id="how-groups-work" tabindex="-1">How groups work <a class="header-anchor" href="#how-groups-work" aria-label="Permalink to &quot;How groups work&quot;">​</a></h2><p>When a user authenticates via OIDC, their groups are automatically included in the token:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user-id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;groups&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;media&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>No scope configuration is required - the <code>groups</code> claim is always included for users who belong to at least one group (an empty array <code>[]</code> is included for users with no groups).</p><h2 id="creating-a-group" tabindex="-1">Creating a group <a class="header-anchor" href="#creating-a-group" aria-label="Permalink to &quot;Creating a group&quot;">​</a></h2><ol><li>Go to <strong>Admin &gt; Groups</strong></li><li>Click <strong>New group</strong></li><li>Enter a name - this exact string will appear in the <code>groups</code> claim (case-sensitive)</li><li>Add an optional description</li><li>Click <strong>Create group</strong></li></ol><h2 id="managing-members" tabindex="-1">Managing members <a class="header-anchor" href="#managing-members" aria-label="Permalink to &quot;Managing members&quot;">​</a></h2><p>Open a group to add or remove members. You can also manage a user&#39;s group memberships from their profile page under <strong>Admin &gt; Users &gt; [user]</strong>.</p><h2 id="configuring-grafana-role-mapping" tabindex="-1">Configuring Grafana role mapping <a class="header-anchor" href="#configuring-grafana-role-mapping" aria-label="Permalink to &quot;Configuring Grafana role mapping&quot;">​</a></h2><p>In Grafana&#39;s OAuth configuration, map the <code>groups</code> claim to Grafana roles:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[auth.generic_oauth]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = GateKeeper</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">client_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = your-client-id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">client_secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = your-client-secret</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auth_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = https://auth.example.com/authorize</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">token_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = https://auth.example.com/oauth/token</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">api_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = https://auth.example.com/userinfo</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">scopes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = openid email profile</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">role_attribute_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = contains(groups[*], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;grafana-admins&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) &amp;&amp; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Admin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> || contains(groups[*], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;grafana-editors&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) &amp;&amp; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Editor&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> || </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Viewer&#39;</span></span></code></pre></div><h2 id="configuring-jellyfin-role-mapping" tabindex="-1">Configuring Jellyfin role mapping <a class="header-anchor" href="#configuring-jellyfin-role-mapping" aria-label="Permalink to &quot;Configuring Jellyfin role mapping&quot;">​</a></h2><p>In Jellyfin with the SSO plugin, map the <code>groups</code> claim to Jellyfin roles by setting the <strong>Admin Roles</strong> field to the name of your admins group.</p><h2 id="difference-between-groups-and-policies" tabindex="-1">Difference between groups and policies <a class="header-anchor" href="#difference-between-groups-and-policies" aria-label="Permalink to &quot;Difference between groups and policies&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Groups</th><th>Policies</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Role mapping inside apps</td><td>Restrict access to apps</td></tr><tr><td><strong>Token</strong></td><td>Included as <code>groups</code> claim</td><td>Not in token</td></tr><tr><td><strong>Use case</strong></td><td>Grafana Admin vs Viewer</td><td>Only certain users can log into an app</td></tr></tbody></table>`,17)])])}const u=i(t,[["render",r]]);export{k as __pageData,u as default};
